<?php require_once __DIR__.'/_base.php'; $title='Provider Dashboard'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=$pdo->query('SELECT id FROM providers WHERE user_id='.(int)$u['id'])->fetchColumn();$st=$pdo->prepare("SELECT status,COUNT(*) c FROM bookings WHERE provider_id=? GROUP BY status");$st->execute([$pid]);$counts=[];foreach($st->fetchAll() as $x)$counts[$x['status']]=$x['c'];$recent=$pdo->prepare('SELECT b.*,u.name user_name,s.service_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN services s ON s.id=b.service_id WHERE b.provider_id=? ORDER BY b.created_at DESC LIMIT 5');$recent->execute([$pid]);?><h2>Provider Dashboard</h2><p class="text-secondary">Welcome, <?=e($u['name'])?>. Manage your services and bookings.</p><div class="row g-3 mb-4"><?php foreach(['Pending','Accepted','Confirmed','Completed','Rejected'] as $x):?><div class="col-md"><div class="stat-card"><div class="text-secondary"><?=e($x)?></div><div class="display-6 fw-bold"><?=$counts[$x]??0?></div></div></div><?php endforeach;?></div><div class="service-card p-4"><h4>Recent requests</h4><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>User</th><th>Service</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach($recent->fetchAll() as $b):?><tr><td>#<?=$b['id']?></td><td><?=e($b['user_name'])?></td><td><?=e($b['service_name'])?></td><td><?=e($b['booking_date'])?></td><td><?=badge($b['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>